        $("#windowResolution").val(windowResolution);
        //end  for salesforce
        $(".navbar").click(function(e) {
            e.preventDefault();
            $(".navbar").toggleClass("active");
            $(".menu-box").toggleClass("active");
        });
        if ($(window).width() < 768) {
            $('li.dropdown span').click(function(e) {
                e.preventDefault();
                $(this).toggleClass('active');
                $(this).parents('li').find('.mob-menu').toggle();
            });
        }

        if ($(window).width() > 1023) {

            $('li.project,div.project').mouseover(function(evt) {
                evt.stopPropagation();
                $('div.project').show();
                return false;
            });

            $('li.project,div.project').mouseout(function(evt) {
                evt.stopPropagation();
                $('div.project').hide();
                return false;
            });
        }

    });
